<?php declare(strict_types=1);use App\Helpers\View;use App\View\Components\Ui;$e=static fn($v)=>View::e((string)$v);$total=array_sum(array_map(fn($x)=>(float)$x['total_amount'],$request['items']));$paid=array_sum(array_map(fn($x)=>(float)$x['amount'],$request['payments']));$statusLabels=['brouillon'=>'Brouillon','soumis'=>'En validation','complement'=>'Complément requis','approuve'=>'Approuvée','refuse'=>'Refusée','annule'=>'Annulée','partiellement_paye'=>'Partiellement payée','paye'=>'Payée'];$status=$request['status'];ob_start();?>
