<section class="feb-hero"><div class="feb-hero-top"><div><span class="feb-eyebrow">FICHE DE BESOIN · <?= $e($request['reference']?:'#'.$request['id']) ?></span><h2><?= $e($request['reference']?:'FEB #'.$request['id']) ?></h2><p><?= $e(trim(($request['chantier_code']??'').' · '.($request['chantier_name']??''),' ·')) ?><?php if(!empty($request['beneficiary_name'])): ?> · <?= $e($request['beneficiary_name']) ?><?php endif; ?></p></div><span class="feb-status feb-status--<?= $e($status) ?>"><?= $e($statusLabels[$status]??ucfirst(str_replace('_',' ',$status))) ?></span></div>
